-- =============================================================================
-- AscEmu Forever 1.60.1
-- Player create master data
-- Build range for range-based tables: min_build=69893, max_build=70009
-- playercreateinfo, playercreateinfo_bars, playercreateinfo_items and playercreateinfo_spell_cast use min_build=69893, max_build=70009; level/stat exact-build rows remain build=70009.
--
-- Combined from:
--   Human, Dwarf, Night Elf, Gnome, Skyborn Alliance,
--   Orc, Undead, Tauren, Troll, Skyborn Horde,
--   initial self-create state extraction,
--   and the seven direct replacement self-create states.
--
-- IMPORTANT:
--   All player-create rows use explicit `race` IDs. Legacy raceMask columns are migrated away completely.
--   Skyborn Alliance/Horde use race=95/96 directly.
-- =============================================================================


SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- -----------------------------------------------------------------------------
-- Schema width updates required for modern build numbers
-- -----------------------------------------------------------------------------
ALTER TABLE `playercreateinfo`
    CHANGE COLUMN `build` `min_build` INT UNSIGNED NOT NULL DEFAULT 18414,
    ADD COLUMN `max_build` INT UNSIGNED NOT NULL DEFAULT 18414 AFTER `min_build`;
UPDATE `playercreateinfo` SET `max_build`=`min_build`;
ALTER TABLE `playercreateinfo_bars`
    CHANGE COLUMN `build` `min_build` INT UNSIGNED NOT NULL DEFAULT 18414,
    ADD COLUMN `max_build` INT UNSIGNED NOT NULL DEFAULT 18414 AFTER `min_build`;
UPDATE `playercreateinfo_bars` SET `max_build`=`min_build`;
ALTER TABLE `playercreateinfo_bars` MODIFY COLUMN `button` SMALLINT UNSIGNED NOT NULL DEFAULT 0;
ALTER TABLE `playercreateinfo_items`
    CHANGE COLUMN `build` `min_build` INT UNSIGNED NOT NULL DEFAULT 12340,
    ADD COLUMN `max_build` INT UNSIGNED NOT NULL DEFAULT 12340 AFTER `min_build`;
UPDATE `playercreateinfo_items` SET `max_build`=`min_build`;
ALTER TABLE `playercreateinfo_spell_cast`
    CHANGE COLUMN `build` `min_build` INT UNSIGNED NOT NULL DEFAULT 18414,
    ADD COLUMN `max_build` INT UNSIGNED NOT NULL DEFAULT 18414 AFTER `min_build`;
UPDATE `playercreateinfo_spell_cast` SET `max_build`=`min_build`;
ALTER TABLE `playercreateinfo_skills` MODIFY COLUMN `min_build` INT UNSIGNED NOT NULL DEFAULT 5875, MODIFY COLUMN `max_build` INT UNSIGNED NOT NULL DEFAULT 18414;
ALTER TABLE `playercreateinfo_skills`
    ADD COLUMN `step` SMALLINT UNSIGNED NOT NULL DEFAULT 0 AFTER `level`,
    ADD COLUMN `startingRank` SMALLINT UNSIGNED NOT NULL DEFAULT 0 AFTER `step`,
    ADD COLUMN `maxRank` SMALLINT UNSIGNED NOT NULL DEFAULT 0 AFTER `startingRank`,
    ADD COLUMN `tempBonus` SMALLINT NOT NULL DEFAULT 0 AFTER `maxRank`,
    ADD COLUMN `permBonus` SMALLINT UNSIGNED NOT NULL DEFAULT 0 AFTER `tempBonus`;
ALTER TABLE `playercreateinfo_spell_learn` MODIFY COLUMN `min_build` INT UNSIGNED NOT NULL DEFAULT 5875, MODIFY COLUMN `max_build` INT UNSIGNED NOT NULL DEFAULT 18414;
ALTER TABLE `player_levelstats` MODIFY COLUMN `build` INT UNSIGNED NOT NULL;
ALTER TABLE `player_classlevelstats` MODIFY COLUMN `build` INT UNSIGNED NOT NULL;

-- -----------------------------------------------------------------------------
-- Unified explicit race IDs for all player-create tables.
-- Legacy race masks are preserved in temporary copies, expanded into one row
-- per concrete race, and only then removed from the live tables.
-- race=0 is retained only for rows whose legacy raceMask was 0 (unrestricted).
-- -----------------------------------------------------------------------------
CREATE TEMPORARY TABLE `_ae_race_ids` (`race` TINYINT UNSIGNED NOT NULL PRIMARY KEY) ENGINE=MEMORY;

-- playercreateinfo_skills
CREATE TEMPORARY TABLE `_ae_old_playercreateinfo_skills` AS SELECT * FROM `playercreateinfo_skills`;

ALTER TABLE `playercreateinfo_skills`
    ADD COLUMN `race` TINYINT UNSIGNED NOT NULL DEFAULT 0 AFTER `max_build`,
    DROP PRIMARY KEY,
    DROP INDEX `unique_index`;

DELETE FROM `playercreateinfo_skills`;

-- Unrestricted legacy rows remain race=0.
SELECT DISTINCT
    p.`min_build`,p.`max_build`,0,0,p.`classMask`,p.`skillid`,p.`level`,p.`note`
FROM `_ae_old_playercreateinfo_skills` p
WHERE p.`raceMask`=0;

-- Every set bit becomes one concrete race row.
SELECT DISTINCT
    p.`min_build`,p.`max_build`,r.`race`,0,p.`classMask`,p.`skillid`,p.`level`,p.`note`
FROM `_ae_old_playercreateinfo_skills` p
JOIN `_ae_race_ids` r ON (CAST(p.`raceMask` AS UNSIGNED) & (CAST(1 AS UNSIGNED) << (r.`race` - 1))) <> 0
WHERE p.`raceMask`<>0;

ALTER TABLE `playercreateinfo_skills`
    DROP COLUMN `raceMask`,
    ADD PRIMARY KEY (`max_build`,`min_build`,`race`,`classMask`,`skillid`) USING BTREE,
    ADD UNIQUE INDEX `unique_index` (`max_build`,`min_build`,`race`,`classMask`,`skillid`) USING BTREE;

DROP TEMPORARY TABLE `_ae_old_playercreateinfo_skills`;

-- playercreateinfo_spell_learn
CREATE TEMPORARY TABLE `_ae_old_playercreateinfo_spell_learn` AS SELECT * FROM `playercreateinfo_spell_learn`;

ALTER TABLE `playercreateinfo_spell_learn`
    ADD COLUMN `race` TINYINT UNSIGNED NOT NULL DEFAULT 0 AFTER `max_build`,
    DROP PRIMARY KEY,
    DROP INDEX `unique_index`;

DELETE FROM `playercreateinfo_spell_learn`;

SELECT DISTINCT
    p.`min_build`,p.`max_build`,0,0,p.`classMask`,p.`spellid`,p.`note`
FROM `_ae_old_playercreateinfo_spell_learn` p
WHERE p.`raceMask`=0;

SELECT DISTINCT
    p.`min_build`,p.`max_build`,r.`race`,0,p.`classMask`,p.`spellid`,p.`note`
FROM `_ae_old_playercreateinfo_spell_learn` p
JOIN `_ae_race_ids` r ON (CAST(p.`raceMask` AS UNSIGNED) & (CAST(1 AS UNSIGNED) << (r.`race` - 1))) <> 0
WHERE p.`raceMask`<>0;

ALTER TABLE `playercreateinfo_spell_learn`
    DROP COLUMN `raceMask`,
    ADD PRIMARY KEY (`min_build`,`max_build`,`race`,`classMask`,`spellid`) USING BTREE,
    ADD UNIQUE INDEX `unique_index` (`min_build`,`max_build`,`race`,`classMask`,`spellid`) USING BTREE;

DROP TEMPORARY TABLE `_ae_old_playercreateinfo_spell_learn`;

-- playercreateinfo_spell_cast
CREATE TEMPORARY TABLE `_ae_old_playercreateinfo_spell_cast` AS SELECT * FROM `playercreateinfo_spell_cast`;

ALTER TABLE `playercreateinfo_spell_cast`
    ADD COLUMN `race` TINYINT UNSIGNED NOT NULL DEFAULT 0 AFTER `max_build`,
    DROP PRIMARY KEY,
    DROP INDEX `unique_index`;

DELETE FROM `playercreateinfo_spell_cast`;

SELECT DISTINCT
    p.`min_build`,p.`max_build`,0,0,p.`classMask`,p.`spellid`,p.`note`
FROM `_ae_old_playercreateinfo_spell_cast` p
WHERE p.`raceMask`=0;

SELECT DISTINCT
    p.`min_build`,p.`max_build`,r.`race`,0,p.`classMask`,p.`spellid`,p.`note`
FROM `_ae_old_playercreateinfo_spell_cast` p
JOIN `_ae_race_ids` r ON (CAST(p.`raceMask` AS UNSIGNED) & (CAST(1 AS UNSIGNED) << (r.`race` - 1))) <> 0
WHERE p.`raceMask`<>0;

ALTER TABLE `playercreateinfo_spell_cast`
    DROP COLUMN `raceMask`,
    ADD PRIMARY KEY (`min_build`,`max_build`,`race`,`classMask`,`spellid`) USING BTREE,
    ADD UNIQUE INDEX `unique_index` (`min_build`,`max_build`,`race`,`classMask`,`spellid`) USING BTREE;

DROP TEMPORARY TABLE `_ae_old_playercreateinfo_spell_cast`;
DROP TEMPORARY TABLE `_ae_race_ids`;

